  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 21, '[17,"- **Starfall** — Dorne (castle): At the Torrentine mouth on Dorne’s far western coast; regional roads and a plausible coastal landing, but no quantified major harbour capacity."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 22, '[18,"- **Sunspear** — Dorne (coastal city): Eastern Dornish hub near Planky Town; inland roads run through eastern and central Dorne."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 23, '[19,"- **Yronwood** — Dorne (castle): Controls the Dornish end of the Boneway and the eastern mountain approach."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 24, '[20,"- **Dragonstone** — The Crownlands (island castle): Island fortress; all ordinary travel requires a vessel."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 25, '[21,"- **Driftmark** — The Crownlands (island seat): Island seat with the port of Hull; all mainland travel requires a vessel."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 26, '[22,"- **Duskendale** — The Crownlands (port town): Blackwater Bay port; the King’s Landing–Maidenpool coastal road passes through it."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 27, '[23,"- **King''s Landing** — The Crownlands (capital city): Road and sea hub: Kingsroad, Goldroad, Roseroad, Blackwater ferry and royal harbour."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 28, '[24,"- **Pyke** — The Iron Islands (island castle): Sea-stack castle; travel to mainland and other islands is by ship."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 29, '[25,"- **Ten Towers** — The Iron Islands (castle): House Harlaw seat on Harlaw; inter-island and mainland movement requires ships."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 30, '[26,"- **Moat Cailin** — The North (fortress): Commands the Kingsroad causeway through the Neck; ordinary army movement is bottlenecked here."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 31, '[27,"- **The Dreadfort** — The North (castle): Eastern North seat reached by regional roads, not directly on the Kingsroad."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 32, '[28,"- **White Harbor** — The North (port city): Principal northern port at the White Knife; connected by road to Winterfell and by sea to eastern ports."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 33, '[29,"- **Winterfell** — The North (castle): Northern road hub on the Kingsroad; regional roads reach White Harbor and the eastern North."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 34, '[30,"- **Highgarden** — The Reach (castle): Reach road hub: Roseroad east, Ocean Road west, regional roads south, Roseroad toward Oldtown."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 35, '[31,"- **Horn Hill** — The Reach (castle): Southern Reach seat on regional roads between Highgarden and Oldtown, toward the marcher country."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 36, '[32,"- **Oldtown** — The Reach (city port): Major southern port and Roseroad terminus; sea access to the Arbor and southern coast."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 37, '[33,"- **The Arbor** — The Reach (island port): Island port across the Redwyne Straits; all mainland travel requires ships."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 38, '[34,"- **Harrenhal** — The Riverlands (castle): Ruined castle beside the God’s Eye near the Kingsroad/Riverlands corridor."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 39, '[35,"- **Maidenpool** — The Riverlands (port town): Walled port on the Bay of Crabs; reached from King’s Landing through Duskendale."]'::jsonb)
