  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 373, '[369,"Storm''s End → Kingswood → Blackwater Rush ferry → King''s Landing → north past the God''s Eye/Harrenhal corridor → Inn at the Crossroads → north east of the Green Fork and the Twins → Neck causeway → Moat Cailin → Winterfell."]'::jsonb),
