  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 375, '[371,"**The Twins is not compulsory** on the standard King''s Landing–Winterfell Kingsroad itinerary. It is a major Green Fork bridge and a useful alternative/strategic route for traffic that needs to cross that river from the western Riverlands. The route planner must not insert it automatically into every north–south trip."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 376, '[372,null]'::jsonb),
