  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 378, '[374,"Casterly Rock / Golden Tooth → Riverrun → Inn at the Crossroads. Golden Tooth guards the main pass between the Westerlands and Riverlands and can block this corridor."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 379, '[375,null]'::jsonb),
