  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 381, '[377,"Inn at the Crossroads → Mountains of the Moon → Bloody Gate → Gates of the Moon → Eyrie ascent. The final ascent is a separate leg and may be closed by winter weather; it is not an ordinary wagon road."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 382, '[378,null]'::jsonb),
