  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 393, '[389,"The Boneway is the eastern pass controlled at the Dornish end by Yronwood. The Prince''s Pass is the western pass guarded from Dorne by the Skyreach/Fowler approach. Keep these as distinct route edges with different hazards and controllers."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 394, '[390,null]'::jsonb),
