  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 400, '[396,null]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 401, '[397,"### Iron Islands"]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 402, '[398,"Pyke and Ten Towers are separate islands. All connections are sea edges; do not add land edges."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 403, '[399,null]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 404, '[400,"## Important transit nodes (not playable locations)"]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 405, '[401,null]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 406, '[402,"Create non-playable route nodes for: Blackwater ferry; Inn at the Crossroads; Neck causeway; Moat Cailin approach; Green Fork bridge at the Twins; Golden Tooth pass; Bloody Gate; Gates of the Moon; Eyrie ascent; Bitterbridge/Mander crossings; Boneway; Prince''s Pass/Skyreach approach; Griffin''s Roost causeway; and harbour/landing waypoints for all ports/islands."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 407, '[403,null]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 408, '[404,"A transit node can be controlled, taxed, blockaded, destroyed, flooded, snowbound or closed by a hostile force. A physical edge can exist while being unavailable to a particular traveller."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 409, '[405,null]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 410, '[406,"## Travel speeds and ETAs (game conventions)"]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 411, '[407,null]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 412, '[408,"- Courier with fresh horses: 40–50 mi/day."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 413, '[409,"- Light mounted party: 25–30 mi/day; pairwise CSV uses 30 as its baseline."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 414, '[410,"- Foot party: 15–18 mi/day; pairwise CSV uses 18."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 415, '[411,"- Large army with baggage: 8–12 mi/day; pairwise CSV uses 10, with lower speeds in passes."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 416, '[412,"- Pass movement: slower and subject to closure; the pairwise CSV uses 20 mounted / 12 foot / 7 large-army miles per day as a baseline."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 417, '[413,"- Ship: 80 sea miles/day baseline; fair wind can be faster. Fleet moving together should be slower than a single fast vessel."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 418, '[414,null]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 419, '[415,"`travel_days = ceil(sum(edge_distance / effective_speed)) + crossing_delay + port_delay + weather_delay + hazard_delay`."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 420, '[416,null]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 421, '[417,"Do not double-add rest days if the baseline speed already assumes ordinary rests. Add special delays for ferry queues, bridge capacity, port loading/unloading, final Eyrie ascent and control permissions."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 422, '[418,null]'::jsonb),
