  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 424, '[420,null]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 425, '[421,"- Dragonstone, Driftmark, Pyke, Ten Towers and the Arbor require ships for ordinary travel."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 426, '[422,"- Starfall is coastal, but do not assume a large harbour/army embarkation capacity without a game rule."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 427, '[423,"- White Harbor, Gulltown, Duskendale, Maidenpool, King''s Landing, Oldtown, Lannisport, Seagard and Sunspear have port/harbour access, but capacity and fleet control still matter."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 428, '[424,"- Rivers should be separate **directed** edges; downstream and upstream speeds differ. Do not presume every stretch of the Trident is navigable by cargo barge."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 429, '[425,"- A ship cannot transport a whole army unless capacity, number of transports, loading time, horses and supplies are modelled."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 430, '[426,null]'::jsonb),
