  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 433, '[429,"Suggested dynamic edge fields: `is_open`, `controller_house_id`, `requires_permission`, `toll_status`, `is_blockaded`, `is_destroyed`, `seasonal_status`, `capacity_class`, `risk_level`, `current_speed_modifier`, `last_state_change_event_id`."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 434, '[430,null]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 435, '[431,"A blocked edge should cause route re-planning, not teleportation. If a bridge is destroyed, remove that edge or mark it unavailable. If a pass is held by a hostile house, route choice should consider permission, siege, force and detour alternatives."]'::jsonb),
  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 436, '[432,null]'::jsonb),
