  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 439, '[435,"Use `travel_nodes` for the 30 playable nodes plus non-playable junctions/ports/passes; use `travel_edges` for the direct connections in the direct-connections CSV; use `travel_orders` for the active journey and saved route sequence."]'::jsonb),
