  ((select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'), 'FULL RESEARCH NOTES', 447, '[443,"The pairwise CSV lists all 435 unordered playable-location pairs, with a shortest route through the direct graph, route nodes, modes, approximate distance range and baseline days. The distance matrix is midpoint miles from that same graph. They are calculated products of this inferred network, not independent canon measurements."]'::jsonb),
